let language = 'zh';
try { if (localStorage.getItem('simple-pdf-language') === 'en') language = 'en'; } catch { /* Optional preference. */ }
export const locale = () => language === 'en' ? 'en-US' : 'zh-CN';
export const currentLanguage = () => language;
export function t(key, ...values) {
  const message = language === 'en' ? messages[key] || key : key;
  return message.replace(/\{(\d+)\}/g, (_, index) => String(values[Number(index)] ?? ''));
}
const staticText = [];
const staticAttributes = [];
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while (walker.nextNode()) {
  const node = walker.currentNode;
  if (node.parentElement.closest('script,style,#project-name')) continue;
  const key = node.data.trim();
  if (/[\u3400-\u9fff]/.test(key)) staticText.push({ node, key, prefix: node.data.match(/^\s*/)[0], suffix: node.data.match(/\s*$/)[0] });
}
for (const node of document.querySelectorAll('*')) {
  for (const attribute of ['title', 'aria-label', 'placeholder', 'content']) {
    if (attribute === 'content' && node.tagName !== 'META') continue;
    const key = node.getAttribute(attribute);
    if (key && /[\u3400-\u9fff]/.test(key)) staticAttributes.push({ node, attribute, key });
  }
}
export function localizeDocument() {
  document.documentElement.lang = locale();
  for (const { node, key, prefix, suffix } of staticText) {
    if (node.isConnected) node.data = prefix + t(key) + suffix;
  }
  for (const { node, attribute, key } of staticAttributes) {
    if (node.isConnected) node.setAttribute(attribute, attribute === 'aria-label' && key === '关闭' ? (language === 'en' ? 'Close' : key) : t(key));
  }
}
export function setLanguage(next) {
  language = next === 'en' ? 'en' : 'zh';
  try { localStorage.setItem('simple-pdf-language', language); } catch { /* Optional preference. */ }
  localizeDocument();
}
localizeDocument();
